create or replace TABLE SZD_PRODUCTION.CORE_REL.T_BROKER_REPORT_LINE (
	MOVEMENT_REF_NUMBER VARCHAR(250) NOT NULL COMMENT 'This is a customs identification number that’s created each time a declaration is submitted\n            The movement reference number for importing or exporting goods. The number generated is bespoke, allowing your goods to be uniquely linked to you. As such, it forms an important part of the audit process for your declarations.',
	ITEM_POSITION NUMBER(38,0) NOT NULL COMMENT 'The number of the Item to which the report line refers. It''s \"Item Number\" in CDS item.',
	TRADER_REFERENCE VARCHAR(250) NOT NULL COMMENT 'Descriptive Attribute - This is a reference assigned by the declarant for the goods covered by the declaration.',
	AUTHORITY_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country of the customs auhtority.',
	CUSTOMS_PROCEDURE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the customs procedure code.',
	CUSTOMS_CLASSIFICATION_SCHEME_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the customs classification scheme.',
	CUSTOMS_TARIFF_CODE_CD VARCHAR(250) NOT NULL COMMENT 'The standardized customs tariff code number.',
	CUSTOMS_PREFERENCE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the customs procedure code.',
	NON_PREFERENTIAL_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country for goods without a preference.',
	PREFERENTIAL_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country for goods with a preference.',
	CUSTOMS_PRODUCT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the customs product.',
	INVOICE_NUMBER VARCHAR(250) COMMENT 'Descriptive Attribute - This is the invoice number given by SAP.',
	GROSS_MASS_MEAS NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The gross mass of the declared goods in kilograms.',
	NET_MASS_MEAS NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - The net mass of the declared goods in kilograms.',
	CHARGE_AMOUNT_CURR_CD VARCHAR(50) NOT NULL COMMENT 'The currency in which the charge amount of an item is specified.',
	CHARGE_AMOUNT_VAL NUMBER(38,5) NOT NULL COMMENT 'Fact - additive - That is the price on the invoice. ',
	ITEM_DESCR VARCHAR(250) NOT NULL COMMENT 'Descriptive Attribute - Text description of the declared goods.',
	ABV_PCT NUMBER(38,5) COMMENT 'Fact - not additive - If the articel is beer, this is the concentration of alcohol.',
	ITEM_PIECE_CNT NUMBER(38,0) NOT NULL COMMENT 'Fact - additive - Count of item pieces. (TODO)',
	ITEM_TARIFF_QTY_UOM_ID NUMBER(38,0) NOT NULL COMMENT 'Id of the unit (e.g. material unit, production line parameter) for the item tariff quantity.',
	ITEM_TARIFF_QTY NUMBER(38,5) COMMENT 'Fact - additive - It is additional unit inforamtion for special products, like alcohol. Regarding alcohol it is the amount of the alcohol. For example it is 300 Liter.',
	ALCOHOLIC_BEVERAGE_TAX_RATE_CD VARCHAR(50) COMMENT 'The unique code of the tax rate for alcoholic beverages within the country.',
	DUTY_EXCISE_RATE_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - Excise duty rate used to calculate excise (per unit) as a descriptive text.',
	EXCISE_PAYMENT_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive - How much excise was actually paid.',
	VALUE_FOR_DUTY_VAL NUMBER(38,5) COMMENT 'Fact - additive - It is the value that is used to determine how much customs duties you need to pay for the item.',
	DUTY_PAYMENT_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive - How much was atucually paid for duty.',
	VALUE_FOR_VAT_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total value of each position''s item for purposes of VAT. This can differ from the \n            Customs Value - for example, it includes any customs duty paid together with \n            freight charges from the EU to the UK boundary. It is \"VAT Value\" in CDS item.',
	VAT_PAYMENT_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive -  It means how much VAT was paid for this position at the moment we submit the declaration.',
	VAT_TAX_ASSESSED_AMOUNT_VAL NUMBER(38,5) COMMENT 'Fact - additive -  It means how much VAT should be paid for this position.',
	SUPPLEMENTARY_CD VARCHAR(50) COMMENT 'Descriptive Attribute - An additional code of the  commedity code (customs tariff number).',
	DOCUMENTS_TXT VARCHAR(1000) COMMENT 'Descriptive Attribute - Additional document references.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_SRC_FILE_NAME VARCHAR(500) COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path.',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source.',
	constraint PK_BROKER_REPORT_LINE primary key (MOVEMENT_REF_NUMBER, ITEM_POSITION, TRADER_REFERENCE)
)COMMENT='Entity - Transactional Events - Snapshot - A broker report line is part of a declaration/shipment declared in the broker report. It describes a single item within the declaration. - Source - Excel-Report from Broker (per Mail)'
;